// Use the mouse to inject energy into the sim.
// Press Space to reverse the direction of the simulation.
// Press Shift to clear the field.
// Press Backspace to reset the simulation to the initial state.

vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 coords = ivec2(fragCoord);
    ivec2 extent = ivec2(iResolution.xy);
    vec2 normalized_extent = iResolution.xy / iResolution.y;

    vec4 field = read_buffer(iChannel0, coords);

    float amp = length(field.xy);
    amp /= amp + 0.2;
    float angle = atan(field.y, field.x);
    float hue = (angle + radians(180.)) / radians(360.);
    vec3 color = hsv2rgb(vec3(hue, 1., amp));

    //color = pow(color, vec3(1./2.2));
    fragColor = vec4(color, 1.);
}

void mainImage( out vec4 field, in vec2 _coords )
{
    ivec2 coords = ivec2(_coords);
    ivec2 extent = ivec2(iResolution.xy);

    bool backspace_is_clicked = bool(texelFetch(iChannel1, ivec2(8, 1), 0).x);
    bool space_is_clicked = bool(texelFetch(iChannel1, ivec2(32, 1), 0).x);
    bool shift_is_clicked = bool(texelFetch(iChannel1, ivec2(16, 1), 0).x);
    bool alt_is_down = bool(texelFetch(iChannel1, ivec2(18, 0), 0).x);
    bool tab_is_down = bool(texelFetch(iChannel1, ivec2(9, 0), 0).x);

    field = read_buffer(iChannel0, coords);

    float q = float(iMouse.z > 0.) * (float(alt_is_down) - float(tab_is_down));

    simulation(field, coords, extent, iChannel0, iMouse.xy, q);

    if(iFrame == 0 || backspace_is_clicked)
    {
        field = initial_state(coords, extent);
    }
    else if (shift_is_clicked)
    {
        // Clear the field.
        field = vec4(0);
    }
    else if(space_is_clicked)
    {
        // Reverse the direction of the simulation.
        vec2 tmp = field.xy;
        field.xy = field.zw;
        field.zw = tmp;
    }
    else if(iMouse.z > 0. && !alt_is_down && !tab_is_down)
    {
        field += mouse_pulse(coords, extent, iMouse, iFrame);
    }
}

const float c = 0.5;
const float damping_coeff = 0.999999;
const float s = 0.5;

#define read_buffer(buffer, uv) texelFetch(buffer, uv, 0)

bool boundary(const ivec2 coords, const ivec2 extent)
{
    return any(lessThan(coords, ivec2(0))) ||     // bottom-left corner
           any(greaterThanEqual(coords, extent));
}

vec2 sample_field(ivec2 coords, const ivec2 extent, const sampler2D channel)
{
    if(boundary(coords, extent))
    {
        // wall
        return vec2(0);
    }

    return read_buffer(channel, coords).xy;
}

// https://www.shadertoy.com/view/ttc3zr
uvec2 murmurHash23(uvec3 src) {
    const uint M = 0x5bd1e995u;
    uvec2 h = uvec2(1190494759u, 2147483647u);
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src.x; h *= M; h ^= src.y; h *= M; h ^= src.z;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

// 2 outputs, 3 inputs
vec2 hash23(vec3 src) {
    uvec2 h = murmurHash23(floatBitsToUint(src));
    return uintBitsToFloat(h & 0x007fffffu | 0x3f800000u) - 1.0;
}

vec4 initial_state(const ivec2 coords, const ivec2 extent)
{
    float r = length(vec2(coords) - vec2(extent)*0.5);
    r *= 20. / float(extent.y);
    vec2 a = hash23(vec3(coords, 0)) * 2. - 1.;
    return vec4(a, a) * exp(-r*r);
}

vec4 mouse_pulse(const ivec2 coords, const ivec2 extent, const vec4 mouse, const int frame)
{
    float r = length(vec2(coords) - mouse.xy);
    r *= 400. / float(extent.y);
    vec2 a = hash23(vec3(coords, frame)) * 2. - 1.;
    return vec4(a, a) * exp(-r*r);
}

vec2 f(const vec2 v0, const ivec2 coords, const ivec2 offset, const ivec2 extent, const sampler2D channel)
{
    vec2 v1 = sample_field(coords + offset, extent, channel);
    vec2 d = v1 - v0;

    // https://www.desmos.com/calculator/bicrgbsxpk d^(1+2a)
    const float a = 0.01;
    return d * pow(dot(d, d), a);
}

float tension(const ivec2 coords, const ivec2 extent, const vec2 mouse)
{
    vec2 d = (vec2(coords) - mouse) * 10. / float(extent.y);
    return 1. / (dot(d, d) + 1.);
}

void simulation(inout vec4 field, const ivec2 coords, const ivec2 extent, const sampler2D channel, const vec2 mouse, const float q)
{
    vec2 a = f(field.xy, coords, +ivec2(1, 0), extent, channel)
           + f(field.xy, coords, -ivec2(1, 0), extent, channel)
           + f(field.xy, coords, +ivec2(0, 1), extent, channel)
           + f(field.xy, coords, -ivec2(0, 1), extent, channel);
    a *= 1. + tension(coords, extent, mouse) * s * q;

    vec2 prev = field.xy;
    field.xy += (field.xy - field.zw) * damping_coeff + a * c * c;
    field.zw = prev;
}

void mainImage( out vec4 field, in vec2 _coords )
{
    ivec2 coords = ivec2(_coords);
    ivec2 extent = ivec2(iResolution.xy);
    field = read_buffer(iChannel0, ivec2(coords));

    bool alt_is_down = bool(texelFetch(iChannel1, ivec2(18, 0), 0).x);
    bool tab_is_down = bool(texelFetch(iChannel1, ivec2(9, 0), 0).x);
    float q = float(iMouse.z > 0.) * (float(alt_is_down) - float(tab_is_down));

    simulation(field, coords, extent, iChannel0, iMouse.xy, q);
}

